#!/usr/bin/env python3\n\nimport sys\n\ndef compute_heat_index(temp_c: float, humidity: float) -> float:\n    """Calculate heat index in Celsius using the NOAA formula (approximation).\n    The formula works in Fahrenheit, so we convert back and forth."""\n    # Convert Celsius to Fahrenheit\n    t_f = temp_c * 9/5 + 32\n    # NOAA heat‑index approximation (valid for t_f >= 80°F and humidity >= 40%)\n    hi_f = (\n        -42.379\n        + 2.04901523 * t_f\n        + 10.14333127 * humidity\n        - 0.22475541 * t_f * humidity\n        - 0.00683783 * t_f * t_f\n        - 0.05481717 * humidity * humidity\n        + 0.00122874 * t_f * t_f * humidity\n        + 0.00085282 * t_f * humidity * humidity\n        - 0.00000199 * t_f * t_f * humidity * humidity\n    )\n    # Convert back to Celsius\n    hi_c = (hi_f - 32) * 5/9\n    return hi_c\n\ndef adjust_for_radiation(heat_index: float, radiation_msv: float) -> float:\n    """Add a small temperature bump per radiation exposure.\n    Every 10 mSv adds 0.5 °C to the apparent temperature."""\n    adjustment = (radiation_msv / 10.0) * 0.5\n    return heat_index + adjustment\n\ndef comfort_level(apparent_temp: float) -> str:\n    """Return a whimsical comfort classification based on apparent temperature."""\n    if apparent_temp < 26:\n        return "Comfortable"\n    elif apparent_temp < 32:\n        return "Caution"\n    elif apparent_temp < 38:\n        return "Danger"\n    else:\n        return "Extreme"\n\ndef main():\n    if len(sys.argv) < 3:\n        print("Usage: heat_index.py <temp_c> <humidity_percent> [radiation_mSv]")\n        sys.exit(1)\n    try:\n        temp_c = float(sys.argv[1])\n        humidity = float(sys.argv[2])\n        radiation = float(sys.argv[3]) if len(sys.argv) > 3 else 0.0\n    except ValueError:\n        print("Error: all arguments must be numbers")\n        sys.exit(1)\n\n    hi = compute_heat_index(temp_c, humidity)\n    hi_adj = adjust_for_radiation(hi, radiation)\n    level = comfort_level(hi_adj)\n\n    print(f"Apparent temperature: {hi_adj:.1f}°C")\n    print(f"Comfort level: {level}")\n\nif __name__ == "__main__":\n    main()
